function tvmazeShow(raw){if(!raw||!Number.isSafeInteger(Number(raw.id))||Number(raw.id)<1||!String(raw.name||'').trim())return null;const image=raw.image&&typeof raw.image==='object'?raw.image:{},summary=String(raw.summary||''),poster=externalUrl(image.original)||externalUrl(image.medium)||noPoster,year=Number(String(raw.premiered||raw.ended||'').slice(0,4))||Number(raw.year)||null;return {id:Number(raw.id),name:String(raw.name).trim(),year,premiered:typeof raw.premiered==='string'?raw.premiered:null,type:raw.type||'',language:raw.language||'',status:raw.status||'',weight:Number(raw.weight)||0,voteCount:Number(raw.voteCount||raw.ratingCount)||0,genres:Array.isArray(raw.genres)?[...new Set(raw.genres.filter(x=>typeof x==='string'))]:[],runtime:Number(raw.averageRuntime||raw.runtime)||0,image:{medium:externalUrl(image.medium)||poster,original:externalUrl(image.original)||poster},summary,officialSite:externalUrl(raw.officialSite)||null,network:raw.network?.name||null,webChannel:raw.webChannel?.name||null,rating:Number(raw.rating?.average)||0,source:externalUrl(raw.url,`https://www.tvmaze.com/shows/${Number(raw.id)}`),description:typeof raw.description==='string'?plainSummary(raw.description):(typeof raw.description==='undefined'?plainSummary(summary):''),reason:raw.reason||'TVmaze kataloğunda bulundu.',label:raw.label||'TVMAZE KATALOĞU',mood:'search',backdrop:typeof raw.backdrop==='string'?raw.backdrop:null};}
