function rememberTvmazeShow(raw){const s=tvmazeShow(raw);if(!s)return null;const existing=byId.get(s.id);if(existing&&!dynamicShows.has(s.id))return existing;const merged=existing?{...existing,...s}:s;dynamicShows.set(merged.id,merged);byId.set(merged.id,merged);return merged;}
